{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2167-06-04 22:34:00",
      "speaker": "Doctor",
      "text": "Hello, I'm Dr. Lee. I understand you came in with muscle cramps and weakness. Can you tell me more about what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2167-06-04 22:35:10",
      "speaker": "Patient",
      "text": "Yes, I’ve been feeling off for about a week. The cramps started in my legs and got worse today. I’ve been drinking salty fluids like I usually do when I feel this way."
    },
    {
      "turn_number": 3,
      "time": "2167-06-04 22:36:20",
      "speaker": "Doctor",
      "text": "I see. You have Addison’s disease, correct? Did you adjust your medications at all?"
    },
    {
      "turn_number": 4,
      "time": "2167-06-04 22:37:05",
      "speaker": "Patient",
      "text": "Yes, I doubled my Florinef yesterday and today, and I also increased my prednisone from 5 to 10 mg. I’ve been stressed and overdid it physically this week."
    },
    {
      "turn_number": 5,
      "time": "2167-06-04 22:38:15",
      "speaker": "Doctor",
      "text": "That makes sense. Your labs show low sodium and high potassium, which fits with adrenal insufficiency. You’re not in full crisis, but we need to correct this. We’ll give you hydrocortisone by mouth and some IV fluids."
    },
    {
      "turn_number": 6,
      "time": "2167-06-04 22:39:30",
      "speaker": "Patient",
      "text": "Okay. I’m glad it’s not another full crisis. Will I need to stay long?"
    },
    {
      "turn_number": 7,
      "time": "2167-06-04 22:40:10",
      "speaker": "Doctor",
      "text": "Likely just overnight. We’ll monitor your labs and symptoms. You already got your first dose of hydrocortisone when you arrived on the floor."
    },
    {
      "turn_number": 8,
      "time": "2167-06-05 06:15:00",
      "speaker": "Doctor",
      "text": "Good morning. Your morning labs show your potassium is coming down, and your kidney function is stable. How are the cramps?"
    },
    {
      "turn_number": 9,
      "time": "2167-06-05 06:16:20",
      "speaker": "Patient",
      "text": "Better, actually. Still a little achy, but not nearly as bad. I had some abdominal cramping too, but it’s improved."
    },
    {
      "turn_number": 10,
      "time": "2167-06-05 06:17:40",
      "speaker": "Doctor",
      "text": "Good. Your lipase was slightly elevated, but your imaging history shows no pancreas issues, so we think it’s from your long-term steroids. The abdominal pain seems related to the adrenal episode."
    },
    {
      "turn_number": 11,
      "time": "2167-06-05 06:18:50",
      "speaker": "Patient",
      "text": "That’s a relief. I was worried it might be something else."
    },
    {
      "turn_number": 12,
      "time": "2167-06-05 10:00:00",
      "speaker": "Doctor",
      "text": "Your repeat labs are back. Sodium is up to 136, potassium is normal at 4.7. That’s a big improvement. We’ve discussed with your endocrinologist, Dr. ___."
    },
    {
      "turn_number": 13,
      "time": "2167-06-05 10:01:10",
      "speaker": "Patient",
      "text": "And what did she say?"
    },
    {
      "turn_number": 14,
      "time": "2167-06-05 10:02:05",
      "speaker": "Doctor",
      "text": "She agrees we should temporarily increase your prednisone to 15 mg daily for two more days, then taper down to 10 mg if you’re feeling better. Your Florinef will stay at 0.2 mg daily until your appointment."
    },
    {
      "turn_number": 15,
      "time": "2167-06-05 10:03:20",
      "speaker": "Patient",
      "text": "Okay, I can do that. Should I go back to my regular dose after that?"
    },
    {
      "turn_number": 16,
      "time": "2167-06-05 10:04:30",
      "speaker": "Doctor",
      "text": "Not yet. Keep the higher dose until you see her. She’ll guide the full taper. The stress from overexertion triggered this, so in the future, you might need to increase steroids earlier during tough weeks."
    },
    {
      "turn_number": 17,
      "time": "2167-06-05 14:30:00",
      "speaker": "Doctor",
      "text": "All your symptoms have resolved, and labs are stable. We’re going to discharge you home in about an hour."
    },
    {
      "turn_number": 18,
      "time": "2167-06-05 14:31:15",
      "speaker": "Patient",
      "text": "Great. Any other instructions?"
    },
    {
      "turn_number": 19,
      "time": "2167-06-05 14:32:30",
      "speaker": "Doctor",
      "text": "Keep taking your Synthroid, and continue the other meds as before. Use cyclobenzaprine if muscle pain returns. Watch for weakness, cramps, or nausea. And follow up with Dr. ___ as scheduled."
    },
    {
      "turn_number": 20,
      "time": "2167-06-05 14:33:45",
      "speaker": "Patient",
      "text": "I will. Thank you for explaining everything."
    },
    {
      "turn_number": 21,
      "time": "2167-06-05 14:35:00",
      "speaker": "Doctor",
      "text": "You’re welcome. You did well. Take care, and we’ll see you only if needed before your appointment."
    }
  ],
  "summary": {
    "admission_start": "2167-06-04 22:34:00",
    "admission_end": "2167-06-05 18:30:00",
    "summary_paragraph": "A woman with a history of Addison’s disease was admitted for muscle cramps and weakness after a physically stressful week. She had self-adjusted her fludrocortisone and prednisone doses but continued to experience symptoms. Labs showed hyponatremia, hyperkalemia, and metabolic acidosis consistent with acute on chronic adrenal insufficiency. She received oral hydrocortisone and IV fluids, with improvement in symptoms and electrolytes. Her prednisone was increased to 15 mg daily and fludrocortisone to 0.2 mg daily per endocrinology guidance. She remained stable, with resolving abdominal discomfort and normalized labs, and was discharged home with a steroid taper plan and follow-up scheduled.",
    "problems": [
      "Glucocorticoid deficiency",
      "Hyposmolality and/or hyponatremia",
      "Acidosis",
      "Hyperpotassemia",
      "Unspecified acquired hypothyroidism",
      "Anxiety state, unspecified",
      "Insomnia, unspecified",
      "Osteoarthrosis, unspecified whether generalized or localized, site unspecified",
      "Long-term (current) use of steroids"
    ]
  }
}
